<script setup lang="ts">
import OcrEvidence from './OcrEvidence.vue'
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import * as api from '../api/checks'
import type { Check, GrammarIssue } from '../api/checks'
import type { DocumentInput } from '../types/document'
import TextEvidence from './TextEvidence.vue'
import ImageEvidence from './ImageEvidence.vue'
import ExperimentChart from './experiments/ExperimentChart.vue'
const props = defineProps<{ manuscriptId: string; submissionId?: string; document: DocumentInput; panel?: string; readonly?: boolean; apply?: (issue: GrammarIssue) => boolean }>()
const emit = defineEmits<{ locate: [from: number, to: number] }>()
const current = ref<Check>(), history = ref<Check[]>([]), busy = ref(false), error = ref(''), progress = ref({ stage: '', processed: 0, total: 0 }), feedback = ref<Record<string, string>>({})
const expected = ref(''), category = ref(''), applied = new Map<string, GrammarIssue>()
let timer: ReturnType<typeof setInterval> | undefined, after = 0, alive = true, ticket = 0, refreshing = false
const kindPanel = (kind: string) => kind === 'CONTENT' ? 'content' : kind === 'IMAGE_TEXT' ? 'image' : 'grammar'
const relevant = computed(() => history.value.filter(item => kindPanel(item.kind) === (props.panel ?? 'content')))
const stale = computed(() => !!current.value && api.signature(props.document) !== expected.value)
const visibleIssues = computed(() => (current.value?.result?.issues ?? []).filter(issue => !feedback.value[issue.id] && (!category.value || issue.category === category.value)))
const active = computed(() => current.value && !api.done(current.value.status))
const state: Record<string, string> = { QUEUED: '排队中', RUNNING: '检查中', WAITING_SERVICE: '等待内容检测服务', WAITING_RESOURCE: '等待模型计算资源', COMPLETED: '检查完成', FAILED: '检查失败', CANCELLED: '已取消', INTERRUPTED: '已中断', RULES_CHECKED: '规则检查完成', MODEL_LOADING: '加载模型', GRAMMAR_CHECKING: '逐句语法检查', IMAGE_TEXT_CHECKING: '逐图比对' }
const relation: Record<string, string> = { MATCH: '对应', CONFLICT: '存在冲突', INSUFFICIENT: '信息不足' }
const categories = computed(() => Object.entries(current.value?.result?.categoryCounts ?? {}))
const chart = computed(() => ({ tooltip: { trigger: 'axis', borderRadius: 0 }, grid: { left: 110, right: 20, top: 20, bottom: 30 }, xAxis: { type: 'value' }, yAxis: { type: 'category', data: categories.value.map(([key]) => key) }, series: [{ type: 'bar', data: categories.value.map(([, count]) => count) }] }))
function stop() { if (timer) clearInterval(timer); timer = undefined }
async function loadHistory(token=ticket) { const rows=await api.list(props.manuscriptId, props.submissionId);if(alive&&token===ticket)history.value=rows }
async function view(check: Check) { stop(); const token=++ticket;try {check=await api.get(check.checkId);if(!alive||token!==ticket)return;current.value = check; expected.value = api.signature(check.document); feedback.value = check.feedback ?? {}; applied.clear(); category.value = ''; after = 0; progress.value = { stage: check.status, processed: 0, total: 0 }; if (!api.done(check.status)) observe(check.checkId, ticket) }catch(value){if(alive&&token===ticket)error.value=value instanceof Error?value.message:'读取检查记录失败'} }
function observe(id: string, token: number) { const refresh = async () => { if (!alive || token !== ticket || refreshing) return; refreshing = true; try { const [result, events] = await Promise.all([api.get(id), api.events(id, after)]); if (!alive || token !== ticket) return; current.value = result; if (events.length) { after = events.at(-1)!.sequence; const last = events.at(-1)!.data; progress.value = { stage: last.stage, processed: last.processed ?? 0, total: last.total ?? 0 } } if (api.done(result.status)) { stop(); await loadHistory() } } catch (value) { error.value = value instanceof Error ? value.message : '读取检查结果失败' } finally { refreshing = false } }; timer = setInterval(() => void refresh(), 1500); void refresh() }
async function start(kind: string) { busy.value = true; error.value = ''; try { const result = await api.start(props.manuscriptId, props.submissionId, kind, props.document); await view(result); await loadHistory() } catch (value) { error.value = value instanceof Error ? value.message : '检查未开始' } finally { busy.value = false } }
function shifted(issue: GrammarIssue) { let shift = 0; for (const old of applied.values()) if (old.field === issue.field && old.end <= issue.start) shift += Array.from(old.replacement).length - (old.end - old.start); return { ...issue, start: issue.start + shift, end: issue.end + shift } }
function locateIssue(issue: GrammarIssue) { const range=shifted(issue);emit('locate',range.start,range.end) }
async function adopt(issue: GrammarIssue) { if (!current.value || stale.value || props.readonly) return; if (!props.apply?.(shifted(issue))) return; applied.set(issue.id, issue); await nextTick(); expected.value = api.signature(props.document); feedback.value[issue.id] = 'ACCEPT'; try { await api.feedback(current.value.checkId, issue.id, 'ACCEPT') } catch { error.value = '正文已更新，采用记录保存失败，可先保存草稿' } }
async function ignore(issue: GrammarIssue) { if (!current.value) return; try { await api.feedback(current.value.checkId, issue.id, 'IGNORE'); feedback.value[issue.id] = 'IGNORE' } catch (value) { error.value = value instanceof Error ? value.message : '记录失败' } }
async function cancel() { if (current.value) { await api.cancel(current.value.checkId); await view(await api.get(current.value.checkId)) } }
async function initialize() { stop(); const token=++ticket; error.value = ''; current.value = undefined; history.value=[]; try { await loadHistory(token);if(!alive||token!==ticket)return; const latest = relevant.value[0]; if (latest) await view(latest) } catch (value) { if(alive&&token===ticket)error.value = value instanceof Error ? value.message : '读取检查历史失败' } }
watch(() => [props.panel, props.submissionId], initialize)
onMounted(initialize); onBeforeUnmount(() => { alive = false; ticket++; stop() })
</script>
<template><section class="manuscript-checks"><div class="check-heading"><h2>{{ panel === 'grammar' ? '语法检查' : panel === 'image' ? '图文一致性' : '内容审核' }}</h2><el-tag v-if="current">{{ state[current.status] }}</el-tag></div><div class="check-actions"><template v-if="panel === 'grammar'"><el-button :loading="busy" @click="start('GRAMMAR_RULES')">快速检查</el-button><el-button type="primary" :loading="busy" @click="start('GRAMMAR_MODEL')">模型语法检查</el-button></template><el-button v-else-if="panel === 'image'" type="primary" :loading="busy" @click="start('IMAGE_TEXT')">检查全部配图</el-button><el-button v-else type="primary" :loading="busy" @click="start('CONTENT')">检查文本与图片复用</el-button><el-button v-if="active" @click="cancel">取消</el-button></div><p v-if="error || current?.error" role="alert" class="work-error">{{ error || current?.error }}</p><p v-if="stale" class="changed-note">稿件已更新，重新检查后可采用建议。</p><p v-if="active" aria-live="polite">{{ state[progress.stage] || state[current!.status] }}<template v-if="progress.total"> · {{ progress.processed }} / {{ progress.total }}</template></p><el-progress v-if="active && progress.total" :percentage="Math.min(100, Math.round(progress.processed / progress.total * 100))" />
  <template v-if="current?.status === 'COMPLETED'"><p class="muted" v-if="current.result?.model">{{ current.result.model }}</p><template v-if="panel === 'grammar'"><div class="check-stats"><div><span>问题建议</span><strong>{{ current.result?.issues?.length ?? 0 }}</strong></div><div><span>已采用</span><strong>{{ Object.values(feedback).filter(v => v === 'ACCEPT').length }}</strong></div><div><span>已忽略</span><strong>{{ Object.values(feedback).filter(v => v === 'IGNORE').length }}</strong></div></div><ExperimentChart v-if="categories.length" title="问题类别" :option="chart as any" /><el-select v-if="categories.length" v-model="category" clearable placeholder="全部类别"><el-option v-for="[label] in categories" :key="label" :label="label" :value="label" /></el-select><section v-for="issue in visibleIssues" :key="issue.id" class="grammar-issue"><div class="check-heading"><el-tag>{{ issue.category }}</el-tag><small>{{ issue.field === 'TITLE' ? '标题' : '正文' }} · {{ issue.engine === 'QWEN' ? '模型建议' : '规则检查' }}</small></div><p><del>{{ issue.original || '（插入位置）' }}</del> → <ins>{{ issue.replacement || '（删除）' }}</ins></p><el-button v-if="issue.field === 'BODY'" size="small" :disabled="stale" @click="locateIssue(issue)">定位</el-button><el-button v-if="!readonly" size="small" type="primary" :disabled="stale" @click="adopt(issue)">采用</el-button><el-button v-if="!readonly" size="small" @click="ignore(issue)">忽略</el-button></section><el-empty v-if="!visibleIssues.length" description="没有待处理建议" :image-size="65" /></template>
  <template v-else-if="panel === 'image'"><el-empty v-if="!current.result?.images?.length" description="本稿没有配图" :image-size="65" /><section v-for="(image, index) in current.result?.images" :key="image.nodeId" class="image-check"><img :src="`/api/files/${image.fileId}`" :alt="image.caption || `配图${index + 1}`" /><div class="check-heading"><strong>配图{{ index + 1 }} · {{ image.caption }}</strong><el-tag :type="image.factStatus === 'CONFLICT' ? 'danger' : 'info'">事实字段{{ relation[image.factStatus] }}</el-tag></div><h3>关联段落</h3><div v-for="match in image.matches.slice(0,3)" :key="`${match.field}:${match.start}`" class="context-match"><span>{{ match.label }} · 语义相似度 {{ match.score.toFixed(4) }}</span><p>{{ match.text }}</p><el-button v-if="match.field === 'BODY'" :disabled="stale" size="small" @click="$emit('locate', match.start!, match.end!)">定位段落</el-button></div><h3>图片文字与正文事实对照</h3><el-table :data="image.fields" size="small"><el-table-column prop="field" label="字段" width="90" /><el-table-column label="图片"><template #default="{row}">{{ row.imageValues.join(' / ') || '—' }}</template></el-table-column><el-table-column label="邻近正文"><template #default="{row}">{{ row.textValues.join(' / ') || '—' }}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{ relation[row.status] }}</template></el-table-column></el-table><p v-if="image.ocrError" class="muted">{{ image.ocrError }}</p><details v-if="image.ocr"><summary>图片文字与识别区域</summary><OcrEvidence :result="image.ocr" :file-id="image.fileId" :image-number="index + 1" source /></details><details v-else-if="image.ocrText"><summary>图片识别文字</summary><p>{{ image.ocrText }}</p></details></section></template>
  <template v-else><TextEvidence :evidence="current.result?.evidence ?? []" :allow-locate="!stale" @locate="(a,b) => $emit('locate', a, b)" /><section v-for="(image, index) in current.result?.imageResults" :key="image.nodeId"><ImageEvidence :evidence="image.evidence" :query-file-id="image.evidence[0]?.queryFileId || ''" :image-number="index + 1" /></section></template></template>
  <el-empty v-else-if="!active" description="使用左侧稿件开始检查" :image-size="65" /><details v-if="relevant.length"><summary>检查历史</summary><button v-for="item in relevant" :key="item.checkId" class="check-history" @click="view(item)">{{ item.kind === 'GRAMMAR_RULES' ? '快速检查' : item.kind === 'GRAMMAR_MODEL' ? '模型语法' : item.kind === 'IMAGE_TEXT' ? '图文检查' : '复用检查' }} · {{ state[item.status] }} · {{ item.checkId.slice(0,8) }}</button></details>
</section></template>
<style scoped>.check-heading,.check-actions{display:flex;gap:10px;justify-content:space-between;align-items:center;flex-wrap:wrap}.check-heading h2{margin:0;font-size:18px}.check-actions{justify-content:flex-start;margin:16px 0}.check-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:16px 0}.check-stats>div{padding:14px;background:color-mix(in srgb,var(--el-color-primary) 7%,var(--canvas))}.check-stats span{font-size:12px;color:var(--muted)}.check-stats strong{display:block;font-size:28px;margin-top:8px}.grammar-issue,.image-check,.context-match{border:1px solid var(--line);padding:14px;margin:14px 0}.grammar-issue p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.8}.grammar-issue del{color:var(--el-color-danger);text-decoration:none}.grammar-issue ins{color:var(--el-color-success);text-decoration:none}.image-check>img{display:block;max-width:100%;max-height:300px;margin:auto auto 15px}.context-match{font-size:13px;line-height:1.7}.context-match>span{color:var(--el-color-primary)}.image-check h3{font-size:14px}.check-history{display:block;width:100%;text-align:left;border:1px solid var(--line);padding:10px;background:transparent;color:inherit;cursor:pointer;margin-top:6px}.changed-note{color:var(--el-color-warning);font-size:13px}.manuscript-checks :deep(.el-button),.manuscript-checks :deep(.el-tag){border-radius:0}</style>
